CREATE TABLE IF NOT EXISTS non_cash_balance_correction_evidence (
  document_id INTEGER PRIMARY KEY REFERENCES documents(id),
  document_sha256 TEXT NOT NULL CHECK(length(document_sha256)=64),
  issue_date TEXT NOT NULL CHECK(length(issue_date)=10),
  amount NUMERIC NOT NULL CHECK(amount>0),
  currency TEXT NOT NULL CHECK(length(currency)=3),
  accounting_rationale TEXT NOT NULL CHECK(length(trim(accounting_rationale)) BETWEEN 1 AND 2000),
  prepared_by TEXT NOT NULL CHECK(length(trim(prepared_by)) BETWEEN 1 AND 256),
  prepared_by_program TEXT NOT NULL CHECK(length(trim(prepared_by_program)) BETWEEN 1 AND 256),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS non_cash_balance_correction_postings (
  document_id INTEGER PRIMARY KEY REFERENCES non_cash_balance_correction_evidence(document_id),
  journal_entry_id INTEGER NOT NULL UNIQUE REFERENCES journal_entries(id),
  document_sha256 TEXT NOT NULL CHECK(length(document_sha256)=64),
  journal_entry_hash TEXT NOT NULL CHECK(length(journal_entry_hash)=64),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
  actor TEXT NOT NULL,
  program TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_evidence_guard_insert BEFORE INSERT ON non_cash_balance_correction_evidence WHEN NOT EXISTS (SELECT 1 FROM documents d WHERE d.id=NEW.document_id AND d.document_type='internal_voucher' AND d.sha256_hash=NEW.document_sha256 AND d.invoice_date=NEW.issue_date AND d.amount_inc_vat=NEW.amount AND upper(d.currency)=upper(NEW.currency) AND d.vat_amount=0) OR EXISTS (SELECT 1 FROM internal_voucher_evidence b WHERE b.document_id=NEW.document_id) BEGIN SELECT RAISE(ABORT, 'non-cash balance correction requires exact immutable document evidence'); END;
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_postings_guard_insert BEFORE INSERT ON non_cash_balance_correction_postings WHEN NOT EXISTS (SELECT 1 FROM non_cash_balance_correction_evidence e JOIN journal_entries j ON j.id=NEW.journal_entry_id WHERE e.document_id=NEW.document_id AND e.document_sha256=NEW.document_sha256 AND j.document_id=NEW.document_id AND j.entry_hash=NEW.journal_entry_hash AND j.source_bank_transaction_id IS NULL AND j.status='posted') BEGIN SELECT RAISE(ABORT, 'non-cash balance correction posting requires exact immutable evidence'); END;
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_evidence_no_update BEFORE UPDATE ON non_cash_balance_correction_evidence BEGIN SELECT RAISE(ABORT, 'non-cash balance correction evidence is append-only'); END;
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_evidence_no_delete BEFORE DELETE ON non_cash_balance_correction_evidence BEGIN SELECT RAISE(ABORT, 'non-cash balance correction evidence is append-only'); END;
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_postings_no_update BEFORE UPDATE ON non_cash_balance_correction_postings BEGIN SELECT RAISE(ABORT, 'non-cash balance correction postings are append-only'); END;
CREATE TRIGGER IF NOT EXISTS non_cash_balance_correction_postings_no_delete BEFORE DELETE ON non_cash_balance_correction_postings BEGIN SELECT RAISE(ABORT, 'non-cash balance correction postings are append-only'); END;
